(() => {
  const out = [];
  const walk = (el, depth) => {
    if (!el || depth > 8) return;
    const r = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    if (el.scrollHeight > innerHeight + 20 || r.bottom > innerHeight + 20) {
      out.push({
        d: depth,
        tag: el.tagName,
        id: el.id,
        cls: String(el.className||'').slice(0,60),
        sh: el.scrollHeight,
        ch: el.clientHeight,
        bottom: Math.round(r.bottom),
        oy: cs.overflowY,
        ox: cs.overflowX,
      });
    }
    for (const c of el.children) walk(c, depth+1);
  };
  walk(document.documentElement, 0);
  return {innerH: innerHeight, htmlOY: getComputedStyle(document.documentElement).overflowY, bodyOY: getComputedStyle(document.body).overflowY, bodyOX: getComputedStyle(document.body).overflowX, hits: out.slice(0, 40)};
})()

